class Solution:
    def maximumSum(self, nums, queries):
        MOD = 10**9 + 7
        NEG = float('-inf')
        n = len(nums)
        t = [None] * (4 * n)

        def mg(a, b):
            f = lambda x, y: NEG if x == NEG or y == NEG else x + y
            return [max(f(a[0], b[2]), f(a[1], b[0])),
                    max(f(a[0], b[3]), f(a[1], b[1])),
                    max(f(a[2], b[2]), f(a[3], b[0])),
                    max(f(a[2], b[3]), f(a[3], b[1]))]

        def build(o, l, r):
            if l == r:
                v = nums[l]
                t[o] = [max(v, 0), NEG, NEG, v]
                return
            m = (l + r) // 2
            build(2*o, l, m); build(2*o+1, m+1, r)
            t[o] = mg(t[2*o], t[2*o+1])

        def upd(o, l, r, p, v):
            if l == r:
                t[o] = [max(v, 0), NEG, NEG, v]
                return
            m = (l + r) // 2
            if p <= m: upd(2*o, l, m, p, v)
            else: upd(2*o+1, m+1, r, p, v)
            t[o] = mg(t[2*o], t[2*o+1])

        build(1, 0, n - 1)
        ans = 0
        for p, x in queries:
            upd(1, 0, n - 1, p, x)
            ans = (ans + t[1][0]) % MOD
        return ans

