class Solution {
    vector<array<long long,4>> t;
    long long NEG;
    array<long long,4> mg(array<long long,4>&a, array<long long,4>&b){
        auto f=[&](long long x, long long y)->long long{
            if(x<=NEG/2 || y<=NEG/2) return NEG;
            return x+y;
        };
        return {max(f(a[0],b[2]),f(a[1],b[0])), max(f(a[0],b[3]),f(a[1],b[1])),
                max(f(a[2],b[2]),f(a[3],b[0])), max(f(a[2],b[3]),f(a[3],b[1]))};
    }
    void build(int o,int l,int r,vector<int>&a){
        if(l==r){ long long v=a[l]; t[o]={max(v,0LL),NEG,NEG,v}; return; }
        int m=(l+r)/2; build(2*o,l,m,a); build(2*o+1,m+1,r,a);
        t[o]=mg(t[2*o],t[2*o+1]);
    }
    void upd(int o,int l,int r,int p,int v){
        if(l==r){ t[o]={max(v,0LL),NEG,NEG,(long long)v}; return; }
        int m=(l+r)/2;
        if(p<=m) upd(2*o,l,m,p,v); else upd(2*o+1,m+1,r,p,v);
        t[o]=mg(t[2*o],t[2*o+1]);
    }
public:
    int maximumSum(vector<int>& nums, vector<vector<int>>& queries){
        int n=nums.size(); NEG=-1e18; t.assign(4*n,{});
        build(1,0,n-1,nums);
        long long ans=0; const long long MOD=1e9+7;
        for(auto&q:queries){ upd(1,0,n-1,q[0],q[1]); ans=(ans+t[1][0])%MOD; }
        return (int)ans;
    }
};

