class Solution {
    long[][] t; long NEG;
    long[] mg(long[] a, long[] b){
        java.util.function.BinaryOperator<Long> f = (x,y) ->
            (x<=NEG/2||y<=NEG/2) ? NEG : x+y;
        long[] r = new long[4];
        r[0]=Math.max(f.apply(a[0],b[2]),f.apply(a[1],b[0]));
        r[1]=Math.max(f.apply(a[0],b[3]),f.apply(a[1],b[1]));
        r[2]=Math.max(f.apply(a[2],b[2]),f.apply(a[3],b[0]));
        r[3]=Math.max(f.apply(a[2],b[3]),f.apply(a[3],b[1]));
        return r;
    }
    void build(int o,int l,int r,int[] a){
        if(l==r){ long v=a[l]; t[o]=new long[]{Math.max(v,0),NEG,NEG,v}; return; }
        int m=(l+r)/2; build(2*o,l,m,a); build(2*o+1,m+1,r,a);
        t[o]=mg(t[2*o],t[2*o+1]);
    }
    void upd(int o,int l,int r,int p,int v){
        if(l==r){ t[o]=new long[]{Math.max(v,0),NEG,NEG,v}; return; }
        int m=(l+r)/2;
        if(p<=m) upd(2*o,l,m,p,v); else upd(2*o+1,m+1,r,p,v);
        t[o]=mg(t[2*o],t[2*o+1]);
    }
    public int maximumSum(int[] nums, int[][] queries){
        int n=nums.length; NEG=-(long)1e18; t=new long[4*n][];
        build(1,0,n-1,nums);
        long ans=0; final long MOD=1000000007L;
        for(int[] q:queries){ upd(1,0,n-1,q[0],q[1]); ans=(ans+t[1][0])%MOD; }
        return (int)ans;
    }
}

