var maximumSum = function(nums, queries) {
    const MOD = 1e9 + 7, NEG = -Infinity, n = nums.length;
    const t = new Array(4 * n);
    const mg = (a, b) => {
        const f = (x, y) => (x === NEG || y === NEG) ? NEG : x + y;
        return [
            Math.max(f(a[0],b[2]), f(a[1],b[0])),
            Math.max(f(a[0],b[3]), f(a[1],b[1])),
            Math.max(f(a[2],b[2]), f(a[3],b[0])),
            Math.max(f(a[2],b[3]), f(a[3],b[1]))
        ];
    };
    function build(o, l, r) {
        if (l === r) { const v = nums[l]; t[o] = [Math.max(v,0), NEG, NEG, v]; return; }
        const m = (l + r) >> 1;
        build(2*o, l, m); build(2*o+1, m+1, r);
        t[o] = mg(t[2*o], t[2*o+1]);
    }
    function upd(o, l, r, p, v) {
        if (l === r) { t[o] = [Math.max(v,0), NEG, NEG, v]; return; }
        const m = (l + r) >> 1;
        if (p <= m) upd(2*o, l, m, p, v); else upd(2*o+1, m+1, r, p, v);
        t[o] = mg(t[2*o], t[2*o+1]);
    }
    build(1, 0, n - 1);
    let ans = 0;
    for (const [p, x] of queries) {
        upd(1, 0, n - 1, p, x);
        ans = (ans + t[1][0]) % MOD;
    }
    return ans;
};
